mapper.select:
select * from (select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='FINPROD_TYPE_TG' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dicttradeMarket on aaa.tradeMarket=dicttradeMarket.ITEM_CODE and dicttradeMarket.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED' left join SYS_DATADICT_LIST dictquote on aaa.quoteType=dictquote.ITEM_CODE and dictquote.DICT_CODE='QUOTE_STYLE' left join SYS_DATADICT_LIST dictms on aaa.matchStatus=dictms.ITEM_CODE and dictms.DICT_CODE='MATCH_STATUS'
order by aaa.finprodType2, aaa.regStatus,aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select decode(reg.trade_status,'03','撤销','有效') as effectiveStatusStr, decode(reg.finprod_type2,'F01','01','02') as finprodType2, reg.finprod_id as finprodId, nvl(fp.finprod_market_id,reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, deal.faceValue as faceValue, case when reg.finprod_type2='F01' then reg.yield when reg.finprod_id in ('F02','F03') then reg.rate else null end as tradeYield, reg.repo_term as termDays, deal.tradeAmt as tradeAmt, reg.totle_trade_id as busiCode, nvl(su.real_name,reg.ou_trader_id) as trader, reg.trade_date as regTradeDate, total.trade_date as confirmTradeDate, reg.counter_id as counterId, mcci.PARTY_ABBR as counterIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, nvl(match.match_status,'02') as matchStatus, reg.remark as remark, reg.trade_status effectiveStatus, case when match.trd_conf_status is null and reg.trade_status in ('01', '02') then '01' when match.trd_conf_status='1' and reg.trade_status in ('01', '02') then '02' when reg.trade_status ='03' then '03' end as regStatus from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, sum(nvl(regdeal.face_value,0))/10000 as faceValue, sum(nvl(regdeal.trade_amt,0)) as tradeAmt from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id left join sys_user su on reg.ou_trader_id=su.user_name where 1=1
AND reg.trade_date= #{sysDate,jdbcType=DATE}
AND reg.trade_date>= #{startDate,jdbcType=DATE}
AND reg.trade_date<=#{endDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND reg.finprod_id in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND reg.trade_status in ('01','02')
AND reg.trade_status = #{effectiveStatus,jdbcType=VARCHAR}
AND nvl(match.match_status,'02') = #{matchStatus,jdbcType=VARCHAR}
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}
AND (case when match.trd_conf_status is null and reg.trade_status in ('01', '02') then '01' when match.trd_conf_status='1' and reg.trade_status in ('01', '02') then '02' when reg.trade_status ='03' then '03' end) in
#{item}

select '流程中' as effectiveStatusStr, decode(reg.finprod_type2,'F01','01','02') as finprodType2, reg.finprod_id as finprodId, nvl(fp.finprod_market_id,reg.term_type) as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.trade_market as tradeMarket, decode(reg.settle_speed,0,'01',1,'02',2,'03') as settleSpeed, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, deal.faceValue as faceValue, case when reg.finprod_type2='F01' then reg.yield when reg.finprod_id in ('F02','F03') then reg.rate else null end as tradeYield, reg.repo_term as termDays, deal.tradeAmt as tradeAmt, reg.totle_trade_id as busiCode, reg.ou_trader_id as trader, reg.trade_date as regTradeDate, null as confirmTradeDate, reg.counter_id as counterId, mcci.PARTY_ABBR as counterIdStr, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, reg.quote_type as quoteType, nvl(match.match_status,'02') as matchStatus, reg.remark as remark, '03' effectiveStatus, '04' as regStatus from wfl_reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id inner join ( select regdeal.totle_trade_id,wm_concat(regdeal.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName, sum(nvl(regdeal.face_value,0))/10000 as faceValue, sum(nvl(regdeal.trade_amt,0)) as tradeAmt from wfl_reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1
AND regdeal.portfolio_id in
#{item}
group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id left join trdquto_match_info match on reg.totle_trade_id=match.pre_trade_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mcci ON reg.counter_id= mcci.party_id where reg.trade_date= #{sysDate,jdbcType=DATE}
and (reg.create_user= #{submitUserId} or reg.update_user= #{submitUserId})
AND reg.ps=#{ps}
AND reg.finprod_type2 in
#{item}
AND reg.finprod_id in
#{item}
AND reg.trade_market=#{tradeMarket,jdbcType=VARCHAR}
AND reg.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND reg.sec_manage_acct_id in
#{item}
AND reg.totle_trade_id like '%' || #{busiCode,jdbcType=VARCHAR} || '%'
AND reg.trade_status in ('01','02')
AND reg.trade_status = #{effectiveStatus,jdbcType=VARCHAR}
AND nvl(match.match_status,'02') = #{matchStatus,jdbcType=VARCHAR}
AND reg.quote_type= #{quoteType,jdbcType=VARCHAR}
AND reg.counter_id= #{counterId,jdbcType=VARCHAR}
AND '04' in
#{item}

if.where:
((aaa.effectiveStatusStr || '|' || sdl.ITEM_VALUE || '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || dictps.ITEM_VALUE || '|' || dicttradeMarket.ITEM_VALUE || '|' || dictsp.ITEM_VALUE
|| '|' || aaa.secManageAcctIdStr || '|' || aaa.busiCode || '|' || aaa.trader
|| '|' || aaa.counterId  || '|' || aaa.counterIdStr || '|' || aaa.portfolioIds  || '|' || aaa.portfolioNames
|| '|' || dictquote.ITEM_VALUE  || '|' || dictms.ITEM_VALUE || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.99')=#{search} or to_char(aaa.faceValue)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.99')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.regTradeDate||'' =#{search}
or aaa.regTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{search}
or replace(aaa.regTradeDate,'-','/')||'' =#{year}||'/'||#{search}
or aaa.confirmTradeDate||'' =#{search}
or aaa.confirmTradeDate||'' =#{year}||'-'||#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{search}
or replace(aaa.confirmTradeDate,'-','/')||'' =#{year}||'/'||#{search}
)

mapper.select:
select reg.ou_party_id as traderid, reg.ou_trader_id as trader, reg.counter_id as counterId, reg.counter_trader as counterTrader, reg.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, reg.ps as ps, reg.quote_type as quoteType, reg.trade_date as regTradeDate, reg.settle_speed as settleSpeed, reg.settle_date as settleDate, reg.ccy as ccy, reg.unit_cprice as unitCprice, reg.yield as yield, reg.exer_yield as exerYield, deal.faceValue as faceValue, reg.delivery_type deliveryType, reg.clear_type as clearType, deal.trdFeeAmt as trdFeeAmt, deal.settleFeeAmt as settleFeeAmt, reg.unit_int as unitInt, reg.unit_fprice as unitFprice, deal.cpriceAmt as cpriceAmt, deal.intAmt as intAmt, deal.fpriceAmt as fpriceAmt, reg.dip_type as distriType, reg.remark as remark, reg.settle_date as exerciseDate, regAdd.Act_Sette_Date as acrExerciseDate, reg.unit_cprice as exercisePrice, reg.repo_term as repoTerm, reg.rate as tradeYield, fp.ccy as secCcy, reg.sett_ccy settCcy, reg.trade_amt tradeAmt, deal.disFaceValue as disFaceValue, reg.m_delivery_type mdeliveryType, reg.v_settle_date as vsettleDate, reg.m_settle_date as msettleDate, deal.mtradeAmt as mtradeAmt, reg.act_repo_term actRepoTerm, reg.term_type as termType from reg_fin_product_deal_total reg left join fin_product fp on fp.finprod_id=reg.finprod_id left join reg_fin_product_deal_total_add regAdd on reg.totle_trade_id=regAdd.Totle_Trade_Id inner join ( select regdeal.totle_trade_id, sum(nvl(regdeal.face_value,0))/10000 as faceValue, sum(regdeal.int_amt) as intAmt, sum(regdeal.cprice_amt) as cpriceAmt, sum(regdeal.fprice_amt) as fpriceAmt, sum(regdeal.trade_amt) as tradeAmt, sum(regdeal.dis_face_value) as disFaceValue, sum(regdeal.m_trade_amt) as mtradeAmt, sum(feeDeal.trdFeeAmt) as trdFeeAmt, sum(feeDeal.settleFeeAmt) as settleFeeAmt from reg_fin_product_deal regdeal inner join ptl_portfolio pp on regdeal.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from reg_trade_fee rf group by rf.trade_id )feeDeal on regdeal.trade_id=feeDeal.trade_id where regdeal.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR} group by regdeal.totle_trade_id )deal on reg.totle_trade_id=deal.totle_trade_id where reg.totle_trade_id= #{totleTradeId,jdbcType=VARCHAR}

select reg.entrust_id as entrustId, reg.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, (nvl(ee.entrust_amt,0) - nvl(efs.ent_finish_amt,0))/10000 unFinshAmt, reg.face_value as faceValue, feeDeal.trdFeeAmt as trdFeeAmt, feeDeal.settleFeeAmt as settleFeeAmt, reg.cprice_amt as cpriceAmt, reg.int_amt as intAmt, reg.fprice_amt as fpriceAmt, EE.PRICE_MODEL as priceModel, EE.BUSINESS_MODEL as businessModel, reg.sec_manage_acct_id as secManageAcctId, stlinfo.sec_acct_name as secManageAcctIdStr, reg.unit_cprice as unitCprice, reg.trade_amt as tradeAmt, reg.m_trade_amt as mtradeAmt, reg.dis_face_value as disFaceValue, reg.rate tradeYield from reg_fin_product_deal reg inner join ptl_portfolio pp on reg.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON reg.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join ( select rf.trade_id,sum(decode(rf.fee_type,'B06',rf.fee_amt)) as trdFeeAmt, sum(decode(rf.fee_type,'B08',rf.fee_amt)) as settleFeeAmt from reg_trade_fee rf group by rf.trade_id )feeDeal on reg.trade_id=feeDeal.trade_id LEFT JOIN ETR_ENTRUST ee ON reg.entrust_id = ee.entrust_id LEFT JOIN ( select t.entrust_id, sum(t.ent_finish_amt) as ent_finish_amt from ETR_FINISH_STATUS t group by t.entrust_id )efs ON ee.Entrust_Id = efs.entrust_id left join stl_sec_acct_info stlinfo on reg.sec_manage_acct_id=stlinfo.sec_acct_id where reg.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR}

select rp.pledge_finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, rp.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, rp.pledge_face_value as pledgePrin, rp.pledge_ratio as pledgeRate from reg_fin_total_pledge rp inner join ptl_portfolio pp on pp.portfolio_id=rp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON rp.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
left join fin_product fp on fp.finprod_id=rp.pledge_finprod_id where rp.totle_trade_id=#{totleTradeId,jdbcType=VARCHAR}

select * from (select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdlStatus on aaa.finprodType2=sdlStatus.ITEM_CODE and sdlStatus.DICT_CODE='STATUS_VALID' left join SYS_DATADICT_LIST sdlbjStatus on aaa.quotationState=sdlbjStatus.ITEM_CODE and sdlbjStatus.DICT_CODE='DEAL_TYPE_IBU' left join SYS_DATADICT_LIST sdlfsStatus on aaa.sendStatus=sdlfsStatus.ITEM_CODE and sdlfsStatus.DICT_CODE='SEND_TYPE_IBU' left join SYS_DATADICT_LIST sdlrole on aaa.quoteRoleType=sdlrole.ITEM_CODE and sdlrole.DICT_CODE='QUOTE_ROLE_TYPE' left join SYS_DATADICT_LIST sdl on aaa.finprodType2=sdl.ITEM_CODE and sdl.DICT_CODE='REG_ASSET_TYPE' left join SYS_DATADICT_LIST dictps on aaa.PS=dictps.ITEM_CODE and dictps.DICT_CODE='PS' left join SYS_DATADICT_LIST dictquote on aaa.quoteType=dictquote.ITEM_CODE and dictquote.DICT_CODE='QUOTE_TYPE' left join SYS_DATADICT_LIST dictsp on aaa.settleSpeed=dictsp.ITEM_CODE and dictsp.DICT_CODE='ACCOUNT_SPEED'
order by aaa.finprodType2, aaa.quotationState,aaa.ps DESC)
order by ${sort} ${direction}

mapper.sql:
select decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01}) as effectiveStatus, case when ib.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end as quotationState, ib.send_status as sendStatus, ib.quote_role_type as quoteRoleType, ib.ps as ps, #{REG_ASSET_TYPE_01} as finprodType2, ib.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, ib.quote_type as quoteType, ib.ou_party_id as traderid, mccit.PARTY_ABBR as traderidStr, ib.ou_trader_id as trader, ibd.cp_party_id as counterId, ibd.PARTY_ABBR as counterIdStr, ibd.cp_trader as counterTrader, ib.settle_speed as settleSpeed, ib.sec_manage_acct_id as secManageAcctId, nvl(ib.share_amt,0)/100 as faceValue, ibd.yield as tradeYield, null as termDays, ib.fprice_amt as tradeAmt, ib.quote_id as quoteId, ibd.execid as execid, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, ib.entrust_id as entrustId, ib.quote_date as quoteDate, total.trade_date as tradeDate, ib.remark from ibu_quote_bond ib left join fin_product fp on ib.finprod_id=fp.finprod_id left join ( select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, ibd.cp_trader cp_trader,ibd.execid,ibd.yield as yield from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='01' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id
union all select ibd.quote_id,wm_concat(ibd.cp_party_id) as cp_party_id,wm_concat(mccic.PARTY_ABBR) as PARTY_ABBR, wm_concat(ibd.cp_trader) cp_trader, ibd.execid,null as yield from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status!='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id group by ibd.quote_id,ibd.execid
union all select ibd.quote_id,ibd.cp_party_id as cp_party_id,mccic.PARTY_ABBR as PARTY_ABBR, ibd.cp_party_id cp_trader,ibd.execid,ibd.yield from ibu_quote_bond_det ibd inner join ibu_quote_bond t1 on ibd.quote_id=t1.quote_id and t1.quote_type='02' and t1.trade_status='07' LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ibd.cp_party_id= mccic.party_id where ibd.trade_status='07' )ibd on ib.quote_id=ibd.quote_id left join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1 group by ir.quote_id)deal on ib.quote_id=deal.quote_id left join trdquto_match_info match on ib.quote_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON ib.ou_party_id= mccit.party_id where 1=1
AND ib.quote_date= #{sysDate,jdbcType=DATE}
AND ib.quote_date>= #{startDate,jdbcType=DATE}
AND ib.quote_date<=#{endDate,jdbcType=DATE}
and (ib.create_user= #{submitUserId} or ib.update_user= #{submitUserId})
AND ib.ps=#{ps}
AND #{REG_ASSET_TYPE_01}=#{regAssetType}
AND ib.finprod_id in
#{item}
AND ib.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ib.sec_manage_acct_id in
#{item}
AND ib.quoteId like '%' || #{quoteId,jdbcType=VARCHAR} || '%'
AND ib.entrustId like '%' || #{entrustId,jdbcType=VARCHAR} || '%'
AND decode(ib.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})=#{effectiveStatus,jdbcType=VARCHAR}
AND ib.quote_type= #{quoteType,jdbcType=VARCHAR}
AND ibd.cp_party_id like '%' || #{counterId,jdbcType=VARCHAR} || '%'
AND (case when ib.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end) in
#{item}
union all
select decode(ic.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01}) as effectiveStatus, case when ic.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end as quotationState, ic.send_status as sendStatus, ic.quote_role_type as quoteRoleType, ic.repo_ps as ps, #{REG_ASSET_TYPE_02} as finprodType2, ic.term_type as finprodId, ic.term_type as finprodMarketId, null as finprodAbbr, ic.quote_type as quoteType, ic.ou_party_id as traderid, mccit.PARTY_ABBR as traderidStr, ic.ou_trader_id as trader, ic.cp_party_id as counterId, mccic.PARTY_ABBR as counterIdStr, ic.cp_trader_id as counterTrader, ic.settle_speed as settleSpeed, ic.sec_manage_acct_id as secManageAcctId, nvl(ic.share_amt,0)/100 as faceValue, ic.rate as tradeYield, ic.term as termDays, ic.fprice_amt as tradeAmt, ic.quote_id as quoteId, ic.execid as execid, deal.portfolioId as portfolioIds, deal.portfolioName as portfolioNames, ic.entrust_id as entrustId, ic.quote_date as quoteDate, total.trade_date as tradeDate, ic.remark from ibu_quote_crep ic left join( select ir.quote_id,wm_concat(ir.portfolio_id) as portfolioId,wm_concat(pp.portfolio_name) portfolioName from ibu_quote_etr_re ir left join ptl_portfolio pp on ir.portfolio_id=pp.portfolio_id
inner JOIN PTL_PORTFOLIO_AUTHORITY PPA ON regdeal.portfolio_id = PPA.PORTFOLIO_ID AND PPA.USER_ID = #{userId}
where 1=1 group by ir.quote_id)deal on ic.quote_id=deal.quote_id left join trdquto_match_info match on ic.quote_id=match.pre_trade_id left join trd_fin_product_deal_total total on match.trd_id=total.totle_trade_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccit ON ic.ou_party_id= mccit.party_id LEFT JOIN MST_CFETS_CUSTOMER_INFO mccic ON ic.cp_party_id= mccic.party_id where 1=1
AND ic.quote_date= #{sysDate,jdbcType=DATE}
AND ic.quote_date>= #{startDate,jdbcType=DATE}
AND ic.quote_date<=#{endDate,jdbcType=DATE}
and (ic.create_user= #{submitUserId} or ic.update_user= #{submitUserId})
AND ic.ps=#{ps}
AND #{REG_ASSET_TYPE_02}=#{regAssetType}
AND ic.term_type in
#{item}
AND ic.settle_speed = #{settleSpeed,jdbcType=VARCHAR}
AND ic.sec_manage_acct_id in
#{item}
AND ic.quoteId like '%' || #{quoteId,jdbcType=VARCHAR} || '%'
AND ic.entrustId like '%' || #{entrustId,jdbcType=VARCHAR} || '%'
AND decode(ic.trade_status,'15',#{STATUS_VALID_03},#{STATUS_VALID_01})=#{effectiveStatus,jdbcType=VARCHAR}
AND ic.quote_type= #{quoteType,jdbcType=VARCHAR}
AND ic.cp_party_id like '%' || #{counterId,jdbcType=VARCHAR} || '%'
AND (case when ic.trade_status in ('07','06','08','15','13') then #{DEAL_TYPE_IBU_02} else #{DEAL_TYPE_IBU_01} end) in
#{item}

