select * from (SELECT aaa.* FROM( select case when T1.trade_status in ('01','02') then #{STATUS_VALID_01} else #{STATUS_VALID_03} end as effectiveStatus, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01}) settleStatus, t1.totle_trade_id as totleTradeId, t1.trade_id as busiCode, t2.entrust_id as entrustId, t1.finprod_type2 as finprodType2, null as tgBusiType, t2.portfolio_id as portfolioId, pp.portfolio_name as portfolioName, t1.finprod_id as finprodId, fp.finprod_market_id as finprodMarketId, fp.finprod_abbr as finprodAbbr, t1.ps as ps, t1.trade_market as tradeMarket, t1.trade_market_mode as tradeMarketMode, t1.settle_speed as settleSpeed, 'T+'||t1.settle_speed assettleSpeedStr, t1.sec_manage_acct_id as secManageAcctId, null as secManageAcctIdStr, nvl(t1.share_amt,0)/100 as faceValue, t1.yield as tradeYield, (t1.mdate-t1.vdate) as termDays, t1.trade_amt as tradeAmt, t1.ccy as ccy, t1.trade_date as confirmTradeDate, t1.settle_date as settleDate, null as execid, t1.counter_id as counterId, null as counterIdStr, t1.remark from trd_product_deal t1 left join trd_product_deal_add t2 on t1.trade_id=t2.trade_id left join ptl_portfolio pp on t2.portfolio_id=pp.portfolio_id left join fin_product fp on t1.finprod_id=fp.finprod_id LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_ORDERS T9 ON T1.TOTLE_TRADE_ID = T9.TRADE_ID WHERE T1.TG_BUSI_TYPE IN (#{PINAN_BUSINESS_TYPE_09},#{PINAN_BUSINESS_TYPE_10},#{PINAN_BUSINESS_TYPE_11}, #{PINAN_BUSINESS_TYPE_20}, #{PINAN_BUSINESS_TYPE_74},#{PINAN_BUSINESS_TYPE_75}) AND T1.trade_date >= #{startDate} AND T1.trade_date <= #{endDate}
AND T1.FINPROD_ID in
#{item}
AND T1.TG_BUSI_TYPE = #{tgBusiType}
AND T1.TOTLE_TRADE_ID LIKE CONCAT('%',CONCAT(#{totleTradeId},'%'))
AND match.exe_id LIKE CONCAT('%',CONCAT(#{execid},'%'))
AND T1.finprod_type2 in
#{item}
AND T1.TRADE_MARKET = #{tradeMarket}
AND T1.PS= #{ps}
AND (case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END)= #{cleanStatus}
AND nvl(T8.SETTLE_STATUS,#{DELIVERY_STATUS_01})= #{settleStatus}
AND T1.trade_status in
#{item}
)aaa left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='SETTLE_STATUS' and aaa.cleanStatus=sdl.ITEM_CODE
order by aaa.confirmTradeDate,aaa.effectiveStatus,aaa.finprodType2,aaa.tgBusiType,aaa.ps)
order by ${sort} ${direction}

if.where:
((
aaa.effectiveStatus || '|' ||aaa.cleanStatus || '|' || aaa.settleStatus
|| '|' ||aaa.totleTradeId || '|' || aaa.finprodType2Str
|| '|' || aaa.tgBusiTypeStr|| '|' || aaa.psStr|| '|' || aaa.tradeMarketStr|| '|' || aaa.tradeMarketModeStr
|| '|' || aaa.finprodMarketId || '|' || aaa.finprodAbbr
|| '|' || aaa.secManageAcctIdStr || '|' || aaa.ccyStr
|| '|' || aaa.execid || '|' || aaa.counterId
|| '|' || aaa.counterIdStr || '|' || aaa.remark
like '%' || #{search} || '%')
or to_char(aaa.faceValue,'FM9999999999999990.90')=#{search} or to_char(aaa.faceValue)=#{search}
or to_char(aaa.tradeYield,'FM99990.9990')=#{search} or  aaa.tradeYield||'' =#{search}
or aaa.termDays||'' =#{search}
or to_char(aaa.tradeAmt,'FM9999999999999990.90')=#{search} or to_char(aaa.tradeAmt)=#{search}
or aaa.confirmTradeDate||'' =#{search}
or aaa.confirmTradeDate||''=#{year}||'-'||#{search}
or replace(aaa.confirmTradeDate,'-','/')||''=#{search}
or replace(aaa.confirmTradeDate,'-','/')||''=#{year}||'/'||#{search}
or aaa.settleDate||'' =#{search}
or aaa.settleDate||''=#{year}||'-'||#{search}
or replace(aaa.settleDate,'-','/')||''=#{search}
or replace(aaa.settleDate,'-','/')||''=#{year}||'/'||#{search}
)
